:root{--page:#f4f5f0;--band:#e3e8df;--text:#373737;--ink:#343b2f;--font-head:'Roboto',system-ui,sans-serif;--font-body:'Figtree',system-ui,sans-serif;--scale:1;--gap:.68rem;--card-ratio:226 / 276}
/* build.mjs writes a :root line above this with the Style settings:
   --page --band --text --ink --font-head --font-body --scale --gap --card-ratio */
html { font-size: calc(clamp(14.75px, calc(9px + 0.56vw), 34px) * var(--scale)); scroll-behavior: smooth; }
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: var(--page); color: var(--text);
  font: 400 1rem/1.85 var(--font-body);
  min-height: 100vh; display: flex; flex-direction: column;
}
main { flex: 1; }
main:has(.about) { background: #fff; }
a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; height: auto; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

.top { background: var(--band); height: 6.6rem; padding: 0 2.7rem; display: flex; align-items: center; justify-content: space-between; }
.logo img { width: 4.35rem; height: 4.35rem; object-fit: contain; }
.logo-text { font: 500 1.3rem var(--font-head); color: var(--ink); letter-spacing: .05rem; }
.top nav { display: flex; gap: 2.3rem; font: 400 .94rem var(--font-head); color: var(--ink); }
.top nav a:hover { opacity: .6; }

.cards { max-width: 56rem; margin: 1.8rem auto 6rem; padding: 0 1rem; display: grid; grid-template-columns: repeat(3, 1fr); gap: 5.15rem; text-align: center; }
.card img { width: 100%; aspect-ratio: var(--card-ratio); object-fit: cover; transition: opacity .25s; }
.card:hover img { opacity: .85; }
.card-title { display: block; margin-top: 1.5rem; font: 400 1.19rem var(--font-head); letter-spacing: .13rem; text-transform: uppercase; color: var(--ink); }
.card-sub { display: block; margin-top: .25rem; font: 400 .875rem var(--font-head); color: var(--ink); }

.page-title { text-align: center; font: 400 1.5rem var(--font-head); text-transform: uppercase; color: var(--ink); margin: 3.4rem 0 2.3rem; }
.masonry { padding: 2.4rem 3.45rem 5.4rem; display: flex; gap: var(--gap); align-items: flex-start; }
.page-title + .masonry { padding-top: 0; }
.m-col { flex: 1; display: flex; flex-direction: column; gap: var(--gap); min-width: 0; }
.m-item img { width: 100%; background: var(--band); }
.m-item { cursor: zoom-in; }
.masonry:not(.ready) { display: grid; grid-template-columns: repeat(4, 1fr); }

.about { background: #fff; padding: 1.8rem 1rem 3.4rem; display: flex; align-items: center; justify-content: center; }
.about-photo { width: 22rem; aspect-ratio: 325 / 400; object-fit: cover; }
.about-card { background: var(--page); width: 22rem; margin-left: -3.4rem; padding: 3.1rem 2.6rem 2.7rem 3.9rem; position: relative; }
.about-card h1 { font: 400 1.5rem var(--font-head); color: var(--ink); margin-bottom: 1.2rem; }
.about-card p { font-size: .85rem; line-height: 2.1; }
.about-card p + p { margin-top: .9rem; }

.banner { height: min(60vh, 28rem); background: #111 center / cover no-repeat; display: flex; align-items: center; justify-content: center; }
.banner h1 { color: #fff; font: 500 2.3rem var(--font-head); text-transform: uppercase; letter-spacing: .07rem; }
.contact { text-align: center; padding: 2.3rem 1rem 5.4rem; }
.contact h2 { font: 400 1.63rem var(--font-head); text-transform: uppercase; color: var(--ink); margin-bottom: 1.5rem; }
.contact .label { font: 500 .75rem var(--font-head); letter-spacing: .11rem; text-transform: uppercase; margin-top: 1.2rem; color: var(--ink); }
.contact a { display: inline-block; font-size: 1rem; }
.contact a:hover { opacity: .6; }

.foot { background: var(--band); height: 6.6rem; padding: 0 2.7rem; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; font-size: .81rem; color: var(--ink); }
.foot svg { width: 1.1rem; height: 1.1rem; }
.foot .totop { justify-self: end; }
.foot a:hover { opacity: .6; }

.lb { position: fixed; inset: 0; z-index: 10; background: color-mix(in srgb, var(--page) 98%, transparent); display: none; align-items: center; justify-content: center; }
.lb.open { display: flex; }
.lb img { max-width: calc(100vw - 9.5rem); max-height: calc(100vh - 5.5rem); width: auto; height: auto; object-fit: contain; user-select: none; }
.lb button { position: absolute; background: none; border: 0; cursor: pointer; color: var(--ink); font: 300 2.3rem/1 var(--font-head); padding: 1.2rem; opacity: .7; }
.lb button:hover { opacity: 1; }
.lb .lb-close { top: .5rem; right: .8rem; font-size: 2rem; }
.lb .lb-prev { left: .5rem; top: 50%; transform: translateY(-50%); }
.lb .lb-next { right: .5rem; top: 50%; transform: translateY(-50%); }
.lb .lb-count { position: absolute; top: 1.5rem; left: 1.75rem; font-size: .81rem; color: var(--ink); }

@media (max-width: 760px) {
  .top { padding: 0 1rem; height: 5.4rem; }
  .logo img { width: 3.5rem; height: 3.5rem; }
  .top nav { gap: 1.35rem; }
  .cards { grid-template-columns: 1fr; gap: 3rem; max-width: 24rem; }
  .masonry { padding: 1.35rem 1rem 4rem; }
  .masonry:not(.ready) { grid-template-columns: repeat(2, 1fr); }
  .about { flex-direction: column; }
  .about-photo { width: 100%; max-width: 24rem; }
  .about-card { width: 100%; max-width: 24rem; margin: -2rem 0 0; padding: 2.3rem 1.75rem; }
  .about-card p { font-size: .95rem; }
  .foot { padding: 0 1rem; }
  .lb img { max-width: 100vw; max-height: calc(100vh - 8rem); }
  .lb .lb-prev, .lb .lb-next { top: auto; bottom: .7rem; transform: none; }
}

